// Generated by tools/voice.py from tools/build-script.js. Do not edit by hand.
window.NARRATION = {"intro": {"src": "audio/intro.mp3", "dur": 22.239, "cues": [{"t": 0.35, "d": 11.285, "kind": "line", "sub": "Between 1095 and 1192, tens of thousands of men and women from Western Europe sewed a cloth cross to their clothes and set out for Jerusalem."}, {"t": 12.055, "d": 4.245, "kind": "line", "sub": "Knights and peasants, bishops and kings. Most never came home."}, {"t": 16.721, "d": 5.099, "kind": "line", "sub": "This is their story, told as the Christian chroniclers of the time told it."}]}, "ch:first:clermont": {"src": "audio/ch-first-clermont.mp3", "dur": 73.889, "cues": [{"t": 0.35, "d": 4.373, "kind": "title", "sub": "27 November 1095. Deus vult!"}, {"t": 5.623, "d": 8.299, "kind": "line", "sub": "At the end of a council in central France, Urban preached in a field outside Clermont, because no church could hold the crowd."}, {"t": 14.342, "d": 5.312, "kind": "line", "sub": "He spoke of Eastern Christians suffering and of Jerusalem in foreign hands."}, {"t": 20.074, "d": 7.36, "kind": "line", "sub": "He told knights who spent their lives fighting each other to take up a different kind of warfare: an armed pilgrimage."}, {"t": 27.854, "d": 3.307, "kind": "line", "sub": "The crowd answered with one cry: God wills it!"}, {"t": 31.581, "d": 3.947, "kind": "line", "sub": "Bishop Adhemar of Le Puy knelt first to take the cross."}, {"t": 35.947, "d": 8.704, "kind": "line", "sub": "People cut cloth into crosses and sewed them onto their shoulders, taking literally Christ's words to take up the cross and follow him."}, {"t": 45.071, "d": 5.376, "kind": "line", "sub": "The council decreed that the journey would count in place of all penance for sin."}, {"t": 51.217, "d": 11.477, "kind": "quote", "sub": "Let those who have formerly been accustomed to contend wickedly in private warfare against the faithful now fight against the infidels. Let those who for a long time have been robbers now become knights.", "source": "Fulcher of Chartres, who was probably present"}, {"t": 63.795, "d": 9.344, "kind": "quote", "sub": "Whoever goes to Jerusalem to free the Church of God, out of devotion alone and not to gain honour or money, may count that journey in place of all penance.", "source": "Decree of the Council of Clermont"}]}, "part:first": {"src": "audio/part-first.mp3", "dur": 15.857, "cues": [{"t": 0.35, "d": 4.693, "kind": "title", "sub": "Part One. The First Crusade. 1095–1099."}, {"t": 5.943, "d": 9.493, "kind": "line", "sub": "Answering a plea from Byzantium, armies of knights and pilgrims cross Europe and Anatolia and take Jerusalem in 1099."}]}, "ch:first:prologue": {"src": "audio/ch-first-prologue.mp3", "dur": 65.083, "cues": [{"t": 0.35, "d": 4.779, "kind": "title", "sub": "1009–1094. A Christian East under threat."}, {"t": 6.029, "d": 2.88, "kind": "line", "sub": "Christianity was born in the East."}, {"t": 9.329, "d": 6.869, "kind": "line", "sub": "For a thousand years, believers had lived and worshipped across Syria, Anatolia and the Holy Land."}, {"t": 16.618, "d": 12.544, "kind": "line", "sub": "Jerusalem had been under Muslim rule since 638, but Western pilgrims still made the long journey to the Church of the Holy Sepulchre, built over the tomb of Christ."}, {"t": 29.582, "d": 8.235, "kind": "line", "sub": "In 1009 the Fatimid caliph al-Hakim had the Holy Sepulchre destroyed, and it was only partly rebuilt."}, {"t": 38.237, "d": 8.725, "kind": "line", "sub": "Then in 1071 the Seljuk Turks crushed the Byzantine army at Manzikert and captured Emperor Romanos IV."}, {"t": 47.382, "d": 3.499, "kind": "line", "sub": "Within a decade most of Anatolia was lost."}, {"t": 51.301, "d": 6.571, "kind": "line", "sub": "Nicaea, where the Nicene Creed was written in 325, became a Turkish capital."}, {"t": 58.291, "d": 3.627, "kind": "line", "sub": "Pilgrims coming home told of a dangerous road."}, {"t": 62.338, "d": 2.325, "kind": "line", "sub": "The Christian East was shrinking."}]}, "ch:first:piacenza": {"src": "audio/ch-first-piacenza.mp3", "dur": 49.826, "cues": [{"t": 0.35, "d": 3.861, "kind": "title", "sub": "March 1095. A plea from Constantinople."}, {"t": 5.111, "d": 7.339, "kind": "line", "sub": "Emperor Alexios I Komnenos had spent fourteen years holding the Byzantine Empire together."}, {"t": 12.87, "d": 10.347, "kind": "line", "sub": "In March 1095 his envoys reached a church council at Piacenza and asked Pope Urban II for Western knights to help fight the Turks."}, {"t": 23.637, "d": 3.072, "kind": "line", "sub": "Urban saw more than a military alliance."}, {"t": 27.129, "d": 5.184, "kind": "line", "sub": "The Great Schism of 1054 had split the Latin and Greek churches."}, {"t": 32.733, "d": 4.288, "kind": "line", "sub": "Coming to the aid of Eastern Christians might help heal that wound."}, {"t": 37.791, "d": 11.285, "kind": "quote", "sub": "An embassy of the emperor of Constantinople came to this synod and humbly begged the lord pope and all the faithful of Christ to bring some help against the pagans for the defence of the holy Church.", "source": "Bernold of Constance, Chronicle"}]}, "ch:first:peoples-crusade": {"src": "audio/ch-first-peoples-crusade.mp3", "dur": 57.147, "cues": [{"t": 0.35, "d": 4.053, "kind": "title", "sub": "April–August 1096. The People's Crusade."}, {"t": 5.303, "d": 6.08, "kind": "line", "sub": "Urban set the departure for 15 August 1096, but many would not wait."}, {"t": 11.803, "d": 6.528, "kind": "line", "sub": "Peter the Hermit gathered tens of thousands of commoners, along with some knights, women and children."}, {"t": 18.751, "d": 3.52, "kind": "line", "sub": "They left Cologne at Easter and walked down the Danube."}, {"t": 22.691, "d": 1.877, "kind": "line", "sub": "The march was disorderly."}, {"t": 24.989, "d": 4.757, "kind": "line", "sub": "Fights over food broke out in Hungary, at Belgrade and at Niš."}, {"t": 30.166, "d": 7.872, "kind": "line", "sub": "Other bands, led by Count Emicho, turned on the Jewish communities of the Rhineland at Speyer, Worms and Mainz."}, {"t": 38.458, "d": 3.819, "kind": "line", "sub": "Some bishops sheltered the Jews in their own palaces."}, {"t": 42.697, "d": 9.323, "kind": "line", "sub": "Christian chroniclers such as Albert of Aachen condemned the killings and saw the bands' later destruction in Hungary as God's judgment."}, {"t": 52.439, "d": 4.288, "kind": "line", "sub": "Peter's column reached Constantinople on 1 August."}]}, "ch:first:civetot": {"src": "audio/ch-first-civetot.mp3", "dur": 41.943, "cues": [{"t": 0.35, "d": 5.227, "kind": "title", "sub": "21 October 1096. Disaster at Civetot."}, {"t": 6.477, "d": 6.443, "kind": "line", "sub": "Alexios ferried Peter's followers across the Bosporus and told them to wait for the princes."}, {"t": 13.339, "d": 1.173, "kind": "line", "sub": "They did not."}, {"t": 14.933, "d": 2.709, "kind": "line", "sub": "Raiding parties pushed toward Nicaea."}, {"t": 18.062, "d": 9.728, "kind": "line", "sub": "In October, while Peter was in Constantinople seeking supplies, the army marched out and walked into an ambush by Sultan Kilij Arslan."}, {"t": 28.21, "d": 2.603, "kind": "line", "sub": "Most were killed or enslaved."}, {"t": 31.233, "d": 3.733, "kind": "line", "sub": "Byzantine ships rescued a few thousand survivors."}, {"t": 35.386, "d": 1.451, "kind": "line", "sub": "Peter survived."}, {"t": 37.257, "d": 4.267, "kind": "line", "sub": "He would march with the main army all the way to Jerusalem."}]}, "ch:first:princes": {"src": "audio/ch-first-princes.mp3", "dur": 54.858, "cues": [{"t": 0.35, "d": 4.736, "kind": "title", "sub": "August 1096 – May 1097. The princes march."}, {"t": 5.986, "d": 3.669, "kind": "line", "sub": "The main army set out on Urban's appointed day."}, {"t": 10.075, "d": 1.408, "kind": "line", "sub": "No king went."}, {"t": 11.903, "d": 3.648, "kind": "line", "sub": "It was led by great lords, each with his own following."}, {"t": 15.971, "d": 3.669, "kind": "line", "sub": "Godfrey of Bouillon marched overland through Hungary."}, {"t": 20.061, "d": 6.208, "kind": "line", "sub": "Raymond of Toulouse, with Bishop Adhemar, took the hard winter road down the Dalmatian coast."}, {"t": 26.689, "d": 4.139, "kind": "line", "sub": "Bohemond sailed from southern Italy across the Adriatic."}, {"t": 31.247, "d": 7.381, "kind": "line", "sub": "Hugh of Vermandois, Robert of Normandy, Robert of Flanders and Stephen of Blois led other contingents."}, {"t": 39.049, "d": 7.339, "kind": "line", "sub": "Historians estimate 60,000 to 100,000 people in all, perhaps 7,000 of them knights."}, {"t": 46.807, "d": 1.877, "kind": "line", "sub": "Most paid their own way."}, {"t": 49.105, "d": 5.333, "kind": "line", "sub": "Crusading cost a fortune, and many sold or mortgaged their land to go."}]}, "ch:first:constantinople": {"src": "audio/ch-first-constantinople.mp3", "dur": 47.249, "cues": [{"t": 0.35, "d": 5.376, "kind": "title", "sub": "December 1096 – April 1097. The emperor's oath."}, {"t": 6.626, "d": 8.256, "kind": "line", "sub": "Constantinople was the greatest Christian city in the world, with ten times the population of any city in the West."}, {"t": 15.302, "d": 4.053, "kind": "line", "sub": "Its walls, churches and relics left the Westerners in awe."}, {"t": 19.775, "d": 3.221, "kind": "line", "sub": "Alexios needed the princes on his side."}, {"t": 23.417, "d": 4.992, "kind": "line", "sub": "He asked each to swear to hand back any former Byzantine land they took."}, {"t": 28.829, "d": 1.152, "kind": "line", "sub": "Most swore."}, {"t": 30.401, "d": 4.459, "kind": "line", "sub": "Raymond would only promise to respect the emperor's life and honour."}, {"t": 35.279, "d": 3.499, "kind": "line", "sub": "Tancred slipped across to Asia rather than swear."}, {"t": 39.198, "d": 3.989, "kind": "line", "sub": "In return, Alexios promised food, guides and troops."}, {"t": 43.607, "d": 3.221, "kind": "line", "sub": "By spring the army was across the Bosporus."}]}, "ch:first:nicaea": {"src": "audio/ch-first-nicaea.mp3", "dur": 47.838, "cues": [{"t": 0.35, "d": 6.08, "kind": "title", "sub": "14 May – 19 June 1097. The siege of Nicaea."}, {"t": 7.33, "d": 8.0, "kind": "line", "sub": "The first target was Nicaea, the city of the first great council of the Church and now the Turkish sultan's capital."}, {"t": 15.75, "d": 3.499, "kind": "line", "sub": "Kilij Arslan was away fighting in the east."}, {"t": 19.669, "d": 3.989, "kind": "line", "sub": "He hurried back on 21 May and was driven off."}, {"t": 24.078, "d": 7.467, "kind": "line", "sub": "The city's west side opened onto a lake, so the Byzantines hauled boats overland and launched them to cut it off."}, {"t": 31.965, "d": 5.845, "kind": "line", "sub": "On 19 June the garrison surrendered to Alexios, not to the crusaders."}, {"t": 38.23, "d": 2.88, "kind": "line", "sub": "Imperial banners went up on the walls."}, {"t": 41.53, "d": 5.888, "kind": "line", "sub": "Many crusaders felt robbed of plunder, but the emperor rewarded the leaders generously."}]}, "ch:first:dorylaeum": {"src": "audio/ch-first-dorylaeum.mp3", "dur": 46.762, "cues": [{"t": 0.35, "d": 4.757, "kind": "title", "sub": "1 July 1097. The battle of Dorylaeum."}, {"t": 6.007, "d": 3.285, "kind": "line", "sub": "To ease supply the army marched in two groups."}, {"t": 9.713, "d": 5.419, "kind": "line", "sub": "Near Dorylaeum, Turkish horse archers surrounded the vanguard under Bohemond."}, {"t": 15.551, "d": 5.696, "kind": "line", "sub": "The Christians pulled into a tight camp and held out for hours under a storm of arrows."}, {"t": 21.667, "d": 3.008, "kind": "line", "sub": "Women carried water to the fighting men."}, {"t": 25.095, "d": 7.616, "kind": "line", "sub": "Then Godfrey and Raymond arrived with the second army, and Bishop Adhemar's troops came over the hills behind the Turks."}, {"t": 33.131, "d": 3.008, "kind": "line", "sub": "The sultan fled and left his camp behind."}, {"t": 36.559, "d": 3.093, "kind": "line", "sub": "The road across Anatolia was open."}, {"t": 40.423, "d": 5.589, "kind": "quote", "sub": "Stand fast all together, trusting in Christ and in the victory of the Holy Cross.", "source": "Gesta Francorum, the word passed along the line"}]}, "ch:first:anatolia": {"src": "audio/ch-first-anatolia.mp3", "dur": 45.065, "cues": [{"t": 0.35, "d": 4.544, "kind": "title", "sub": "July – October 1097. Across Anatolia."}, {"t": 5.794, "d": 3.797, "kind": "line", "sub": "The summer march across the dry interior was brutal."}, {"t": 10.011, "d": 2.581, "kind": "line", "sub": "Men and horses died of thirst."}, {"t": 13.013, "d": 7.04, "kind": "line", "sub": "Knights rode oxen, and the anonymous author of the Gesta says goats, sheep and dogs carried the baggage."}, {"t": 20.473, "d": 6.741, "kind": "line", "sub": "After Heraclea, Tancred and Baldwin of Boulogne turned south through the Cilician Gates to Tarsus."}, {"t": 27.634, "d": 8.939, "kind": "line", "sub": "The main army took the longer road north through Caesarea and over the Anti-Taurus mountains, where Armenian Christians welcomed them."}, {"t": 36.993, "d": 3.2, "kind": "line", "sub": "At Marash, Baldwin's wife Godehilde died."}, {"t": 40.613, "d": 4.032, "kind": "line", "sub": "Soon after, he rode east with a small company of knights."}]}, "ch:first:antioch-siege": {"src": "audio/ch-first-antioch-siege.mp3", "dur": 43.763, "cues": [{"t": 0.35, "d": 5.376, "kind": "title", "sub": "21 October 1097. Before the walls of Antioch."}, {"t": 6.626, "d": 3.605, "kind": "line", "sub": "Antioch was one of the oldest centres of the faith."}, {"t": 10.651, "d": 9.109, "kind": "line", "sub": "By tradition St Peter led the church there, and it was where believers were first called Christians (Acts 11:26)."}, {"t": 20.181, "d": 5.653, "kind": "line", "sub": "Its walls ran for miles, with some 400 towers climbing up the mountainside."}, {"t": 26.254, "d": 2.56, "kind": "line", "sub": "The crusaders could not surround it."}, {"t": 29.234, "d": 4.053, "kind": "line", "sub": "The siege lasted almost eight months through a hard winter."}, {"t": 33.707, "d": 4.992, "kind": "line", "sub": "Famine set in, foraging parties were ambushed, and some men deserted."}, {"t": 39.119, "d": 4.224, "kind": "line", "sub": "Two relief armies from Damascus and Aleppo were beaten off."}]}, "ch:first:edessa": {"src": "audio/ch-first-edessa.mp3", "dur": 40.115, "cues": [{"t": 0.35, "d": 4.352, "kind": "title", "sub": "10 March 1098. The first crusader state."}, {"t": 5.602, "d": 6.187, "kind": "line", "sub": "Baldwin reached Edessa, an Armenian Christian city ruled by a lord named Thoros."}, {"t": 12.209, "d": 3.52, "kind": "line", "sub": "Thoros adopted Baldwin as his son and heir."}, {"t": 16.149, "d": 4.736, "kind": "line", "sub": "Weeks later a revolt overthrew Thoros, and the crowd killed him."}, {"t": 21.305, "d": 3.648, "kind": "line", "sub": "Whether Baldwin had a hand in it is still debated."}, {"t": 25.373, "d": 4.629, "kind": "line", "sub": "On 10 March 1098 he became Count of Edessa."}, {"t": 30.422, "d": 4.459, "kind": "line", "sub": "The County of Edessa was the first state founded by the crusaders."}, {"t": 35.301, "d": 4.395, "kind": "line", "sub": "Its money and food would help keep the army alive at Antioch."}]}, "ch:first:antioch-falls": {"src": "audio/ch-first-antioch-falls.mp3", "dur": 32.363, "cues": [{"t": 0.35, "d": 3.755, "kind": "title", "sub": "3 June 1098. Antioch falls."}, {"t": 5.005, "d": 5.995, "kind": "line", "sub": "Bohemond made a secret deal with Firuz, a convert who commanded a tower on the walls."}, {"t": 11.419, "d": 8.363, "kind": "line", "sub": "Before dawn on 3 June, a small party climbed a leather ladder into the Tower of the Two Sisters and opened a gate."}, {"t": 20.202, "d": 4.693, "kind": "line", "sub": "The city fell within hours, though its citadel on the mountain held out."}, {"t": 25.315, "d": 2.837, "kind": "line", "sub": "Bohemond claimed the city for himself."}, {"t": 28.573, "d": 3.371, "kind": "line", "sub": "It would become the Principality of Antioch."}]}, "ch:first:holy-lance": {"src": "audio/ch-first-holy-lance.mp3", "dur": 66.759, "cues": [{"t": 0.35, "d": 4.928, "kind": "title", "sub": "14–28 June 1098. The Holy Lance."}, {"t": 6.178, "d": 3.648, "kind": "line", "sub": "Two days later the besiegers became the besieged."}, {"t": 10.246, "d": 4.117, "kind": "line", "sub": "Kerbogha, ruler of Mosul, arrived with a huge army."}, {"t": 14.783, "d": 5.717, "kind": "line", "sub": "Trapped and starving, some crusaders let themselves down the walls on ropes and fled."}, {"t": 20.921, "d": 5.397, "kind": "line", "sub": "Then Peter Bartholomew, a poor pilgrim, reported visions of St Andrew."}, {"t": 26.738, "d": 6.763, "kind": "line", "sub": "On 14 June a lance point was dug up beneath the floor of the Cathedral of St Peter."}, {"t": 33.921, "d": 3.861, "kind": "line", "sub": "Many believed it was the spear that pierced Christ's side."}, {"t": 38.202, "d": 3.477, "kind": "line", "sub": "Adhemar had doubts, but the army's spirit came back."}, {"t": 42.099, "d": 9.472, "kind": "line", "sub": "After three days of fasting and processions, the army marched out on 28 June in six divisions while priests prayed on the walls."}, {"t": 51.991, "d": 3.627, "kind": "line", "sub": "Kerbogha's divided coalition broke and fled."}, {"t": 56.388, "d": 9.621, "kind": "quote", "sub": "There came out from the mountains countless armies on white horses, whose banners were all white. Their leaders were St George, St Mercurius and St Demetrius.", "source": "Gesta Francorum (abridged)"}]}, "ch:first:road-south": {"src": "audio/ch-first-road-south.mp3", "dur": 55.541, "cues": [{"t": 0.35, "d": 5.333, "kind": "title", "sub": "August 1098 – June 1099. The road to Jerusalem."}, {"t": 6.583, "d": 4.608, "kind": "line", "sub": "On 1 August 1098 Bishop Adhemar died of plague."}, {"t": 11.611, "d": 4.885, "kind": "line", "sub": "Without him, the princes quarrelled for months over who would hold Antioch."}, {"t": 16.917, "d": 9.429, "kind": "line", "sub": "That winter, at the siege of Ma'arra, famine became so severe that the chroniclers recorded, with shame, that some crusaders ate the dead."}, {"t": 26.766, "d": 2.709, "kind": "line", "sub": "The ordinary pilgrims forced the issue."}, {"t": 29.895, "d": 4.011, "kind": "line", "sub": "They tore down the walls of Ma'arra so the army could not stay."}, {"t": 34.326, "d": 6.485, "kind": "line", "sub": "In January 1099 Raymond walked out barefoot as a pilgrim and led the march south."}, {"t": 41.231, "d": 2.859, "kind": "line", "sub": "Bohemond stayed behind in Antioch."}, {"t": 44.51, "d": 4.331, "kind": "line", "sub": "After a long siege at Arqa, the army moved fast down the coast."}, {"t": 49.261, "d": 2.88, "kind": "line", "sub": "Local rulers paid them to pass by."}, {"t": 52.561, "d": 2.56, "kind": "line", "sub": "In early June they reached Ramla."}]}, "ch:first:jerusalem": {"src": "audio/ch-first-jerusalem.mp3", "dur": 68.658, "cues": [{"t": 0.35, "d": 5.227, "kind": "title", "sub": "7 June – 15 July 1099. Jerusalem."}, {"t": 6.477, "d": 4.48, "kind": "line", "sub": "On 7 June the army saw Jerusalem, and many wept."}, {"t": 11.377, "d": 7.936, "kind": "line", "sub": "Of the great host that had left, about 1,300 knights and perhaps 12,000 men on foot remained."}, {"t": 19.733, "d": 3.029, "kind": "line", "sub": "A first assault failed for lack of ladders."}, {"t": 23.182, "d": 3.008, "kind": "line", "sub": "Water was scarce and the heat was crushing."}, {"t": 26.61, "d": 5.099, "kind": "line", "sub": "When Genoese ships arrived at Jaffa, their timber went into siege towers."}, {"t": 32.129, "d": 9.408, "kind": "line", "sub": "On 8 July the whole army walked barefoot in procession around the walls, and Peter the Hermit preached to them on the Mount of Olives."}, {"t": 41.957, "d": 6.037, "kind": "line", "sub": "On 15 July Godfrey's tower reached the north wall, and the city fell that day."}, {"t": 48.414, "d": 5.888, "kind": "line", "sub": "The chroniclers record a terrible slaughter of its Muslim and Jewish inhabitants."}, {"t": 54.722, "d": 4.715, "kind": "line", "sub": "Afterwards the crusaders went to the Holy Sepulchre to give thanks."}, {"t": 60.207, "d": 7.701, "kind": "quote", "sub": "This day, I say, will be famous in all future ages, for it turned our labours and sorrows into joy and exultation.", "source": "Raymond of Aguilers, chaplain to Raymond of Toulouse"}]}, "ch:first:defender": {"src": "audio/ch-first-defender.mp3", "dur": 30.327, "cues": [{"t": 0.35, "d": 4.949, "kind": "title", "sub": "22 July 1099. A crown of thorns."}, {"t": 6.199, "d": 2.539, "kind": "line", "sub": "The leaders met to choose a ruler."}, {"t": 9.158, "d": 2.304, "kind": "line", "sub": "Raymond refused the crown."}, {"t": 11.882, "d": 1.856, "kind": "line", "sub": "They turned to Godfrey."}, {"t": 14.158, "d": 3.605, "kind": "line", "sub": "Godfrey agreed to govern but would not be called king."}, {"t": 18.183, "d": 5.717, "kind": "line", "sub": "He took the title Advocatus Sancti Sepulchri, Defender of the Holy Sepulchre."}, {"t": 24.671, "d": 4.907, "kind": "quote", "sub": "He would not wear a crown of gold where his Saviour had worn a crown of thorns.", "source": "William of Tyre, writing c. 1170–1184 (paraphrased)"}]}, "ch:first:ascalon": {"src": "audio/ch-first-ascalon.mp3", "dur": 34.81, "cues": [{"t": 0.35, "d": 4.523, "kind": "title", "sub": "12 August 1099. The battle of Ascalon."}, {"t": 5.773, "d": 6.357, "kind": "line", "sub": "A Fatimid army under the vizier al-Afdal marched from Egypt to retake Jerusalem."}, {"t": 12.55, "d": 2.581, "kind": "line", "sub": "Godfrey led the crusaders out."}, {"t": 15.551, "d": 5.632, "kind": "line", "sub": "Before them went a relic of the True Cross, found in the city only days before."}, {"t": 21.603, "d": 6.613, "kind": "line", "sub": "At dawn on 12 August they surprised the Egyptian camp outside Ascalon and routed it."}, {"t": 28.637, "d": 2.219, "kind": "line", "sub": "Jerusalem was secure."}, {"t": 31.275, "d": 3.115, "kind": "line", "sub": "The crusade had done what it set out to do."}]}, "ch:first:epilogue": {"src": "audio/ch-first-epilogue.mp3", "dur": 51.014, "cues": [{"t": 0.35, "d": 3.456, "kind": "title", "sub": "1099 and after. What came after."}, {"t": 4.706, "d": 3.819, "kind": "line", "sub": "With their vows fulfilled, most crusaders sailed home."}, {"t": 8.945, "d": 4.544, "kind": "line", "sub": "Godfrey stayed with perhaps 300 knights to hold Jerusalem."}, {"t": 13.909, "d": 6.464, "kind": "line", "sub": "He died in July 1100, and his brother Baldwin became the first King of Jerusalem."}, {"t": 20.793, "d": 9.963, "kind": "line", "sub": "Pope Urban II died in Rome on 29 July 1099, fourteen days after Jerusalem fell, before the news could reach him."}, {"t": 31.175, "d": 7.829, "kind": "line", "sub": "The crusaders' states now stood in the East: Edessa, Antioch, Jerusalem, and from 1109 Tripoli."}, {"t": 39.425, "d": 6.357, "kind": "line", "sub": "When Edessa fell in 1144, Christendom would answer again with the Second Crusade."}, {"t": 46.552, "d": 3.712, "kind": "quote", "sub": "For we who were Westerners have now become Easterners.", "source": "Fulcher of Chartres, who settled in Jerusalem"}]}, "sc:first:dorylaeum": {"src": "audio/sc-first-dorylaeum.mp3", "dur": 61.727, "cues": [{"t": 0.35, "d": 2.048, "kind": "title", "sub": "The battle of Dorylaeum."}, {"t": 3.298, "d": 11.925, "kind": "phase", "sub": "Dawn, 1 July 1097. Bohemond's half of the army has camped by a river near Dorylaeum. The other half, under Godfrey and Raymond, is some miles behind.", "phase": 0}, {"t": 15.923, "d": 7.168, "kind": "phase", "sub": "Turkish horse archers pour over the hills and surround the camp. Arrows fall like rain on the Christians.", "phase": 1}, {"t": 23.791, "d": 10.197, "kind": "phase", "sub": "Bohemond sends riders for help and orders everyone to hold together. The army draws into a tight ring, and the women carry water to the fighting men.", "phase": 2}, {"t": 34.689, "d": 8.917, "kind": "phase", "sub": "Around midday the second army arrives. Godfrey and Hugh charge in from the west, then Raymond. Now the Turks are fighting on two fronts.", "phase": 3}, {"t": 44.306, "d": 9.067, "kind": "phase", "sub": "Bishop Adhemar, who had led his men around through the hills, appears behind the Turkish camp. Caught between three forces, the Turks break.", "phase": 4}, {"t": 54.073, "d": 6.955, "kind": "phase", "sub": "Kilij Arslan flees, leaving his camp and treasure behind. The road across Anatolia is open.", "phase": 5}]}, "sc:first:antioch": {"src": "audio/sc-first-antioch.mp3", "dur": 57.55, "cues": [{"t": 0.35, "d": 2.133, "kind": "title", "sub": "The battle of Antioch."}, {"t": 3.383, "d": 11.797, "kind": "phase", "sub": "Dawn, 28 June 1098. After three days of fasting and prayer, the starving army marches out of Antioch through the Bridge Gate. Priests pray on the walls.", "phase": 0}, {"t": 15.881, "d": 8.085, "kind": "phase", "sub": "Kerbogha lets them cross, hoping to destroy the whole army at once. He sends horsemen around to strike them from behind.", "phase": 1}, {"t": 24.666, "d": 10.112, "kind": "phase", "sub": "Bohemond's division turns to hold the rear while the rest of the line advances. Raymond of Aguilers carries the Holy Lance before Adhemar's men.", "phase": 2}, {"t": 35.478, "d": 10.645, "kind": "phase", "sub": "Then, as the Gesta tells it, an army of riders on white horses came down from the mountains, led by St George, St Demetrius and St Mercurius.", "phase": 3}, {"t": 46.823, "d": 10.027, "kind": "phase", "sub": "Kerbogha's allies, already quarrelling, abandon him. His army breaks and flees. The crusaders take his camp, and that day the citadel surrenders.", "phase": 4}]}, "sc:first:jerusalem": {"src": "audio/sc-first-jerusalem.mp3", "dur": 66.634, "cues": [{"t": 0.35, "d": 2.027, "kind": "title", "sub": "The fall of Jerusalem."}, {"t": 3.277, "d": 11.435, "kind": "phase", "sub": "Night of 13 July. Godfrey's men take their siege tower apart and rebuild it opposite a weaker stretch of the north wall, east of where the defenders expect it.", "phase": 0}, {"t": 15.411, "d": 10.773, "kind": "phase", "sub": "14 July. A battering ram smashes the outer wall so the towers can roll close. The defenders answer with stones, arrows and Greek fire.", "phase": 1}, {"t": 26.885, "d": 7.424, "kind": "phase", "sub": "On Mount Zion in the south, Raymond's tower meets the fiercest defence of all. The fighting goes on all day.", "phase": 2}, {"t": 35.009, "d": 13.376, "kind": "phase", "sub": "Midday, 15 July. Godfrey's tower reaches the north wall. A bridge drops onto the wall, and the brothers Litold and Engelbert of Tournai are the first across, with Godfrey behind them.", "phase": 3}, {"t": 49.085, "d": 8.64, "kind": "phase", "sub": "The north wall falls and the crusaders pour into the city. In the south, the governor surrenders the Tower of David to Raymond.", "phase": 4}, {"t": 58.425, "d": 7.509, "kind": "phase", "sub": "When the fighting ended, the crusaders went to the Church of the Holy Sepulchre to give thanks at the tomb of Christ.", "phase": 5}]}, "sc:first:ascalon": {"src": "audio/sc-first-ascalon.mp3", "dur": 50.19, "cues": [{"t": 0.35, "d": 2.069, "kind": "title", "sub": "The battle of Ascalon."}, {"t": 3.319, "d": 13.781, "kind": "phase", "sub": "Dawn, 12 August 1099. The crusaders march south in battle order, with the newly found relic of the True Cross carried before them. Raymond holds the right by the sea, Godfrey the left.", "phase": 0}, {"t": 17.801, "d": 5.205, "kind": "phase", "sub": "Al-Afdal's army is camped before Ascalon, and the attack catches it unready.", "phase": 1}, {"t": 23.706, "d": 7.147, "kind": "phase", "sub": "Robert of Normandy charges straight at al-Afdal's standard and captures it. The whole line follows him in.", "phase": 2}, {"t": 31.553, "d": 9.899, "kind": "phase", "sub": "The Fatimid army breaks. Some flee into Ascalon, some into the sea, and some hide in the sycamore groves, which the crusaders set on fire.", "phase": 3}, {"t": 42.151, "d": 7.339, "kind": "phase", "sub": "Al-Afdal escapes by ship to Egypt. Jerusalem is safe, and the crusade has done what it set out to do.", "phase": 4}]}, "sc:first:clermont": {"src": "audio/sc-first-clermont.mp3", "dur": 51.342, "cues": [{"t": 0.35, "d": 2.347, "kind": "title", "sub": "Urban II at Clermont."}, {"t": 3.597, "d": 12.395, "kind": "phase", "sub": "27 November 1095. The council of Clermont is over. No church can hold the crowd, so Urban II speaks from a platform in a field outside the town.", "phase": 0}, {"t": 16.691, "d": 10.709, "kind": "phase", "sub": "He speaks of Eastern Christians attacked by the Turks, of churches destroyed, and of Jerusalem in foreign hands. He tells the knights to stop fighting each other.", "phase": 1}, {"t": 28.101, "d": 4.331, "kind": "phase", "sub": "The crowd answers with one cry: Deus vult! God wills it!", "phase": 2}, {"t": 33.131, "d": 6.805, "kind": "phase", "sub": "Adhemar, Bishop of Le Puy, comes forward and kneels before the pope. He is the first to take the cross.", "phase": 3}, {"t": 40.637, "d": 10.005, "kind": "phase", "sub": "Many follow him. They cut cloth into crosses and sew them on their shoulders. The council decrees that the journey will count in place of all penance.", "phase": 4}]}, "sc:first:lance": {"src": "audio/sc-first-lance.mp3", "dur": 48.889, "cues": [{"t": 0.35, "d": 2.368, "kind": "title", "sub": "The finding of the Holy Lance."}, {"t": 3.618, "d": 11.477, "kind": "phase", "sub": "14 June 1098. Peter Bartholomew, a poor pilgrim, says St Andrew showed him where the lance lies: under the floor of the Cathedral of St Peter.", "phase": 0}, {"t": 15.795, "d": 7.68, "kind": "phase", "sub": "Twelve men dig from morning until evening. They find nothing. Count Raymond leaves to keep watch on the citadel.", "phase": 1}, {"t": 24.175, "d": 6.528, "kind": "phase", "sub": "Peter Bartholomew, barefoot and in his shirt, leaps down into the pit and tells the others to pray.", "phase": 2}, {"t": 31.403, "d": 7.787, "kind": "phase", "sub": "The point of a lance appears in the earth. Raymond of Aguilers writes that he kissed it as soon as the point appeared.", "phase": 3}, {"t": 39.89, "d": 8.299, "kind": "phase", "sub": "The news spreads through the starving city. Many believe it is the spear that pierced Christ's side, and the army's spirit comes back.", "phase": 4}]}, "sc:first:procession": {"src": "audio/sc-first-procession.mp3", "dur": 50.19, "cues": [{"t": 0.35, "d": 2.709, "kind": "title", "sub": "The procession around Jerusalem."}, {"t": 3.959, "d": 11.669, "kind": "phase", "sub": "8 July 1099. After a three-day fast, the whole army sets out to walk barefoot around Jerusalem. Clergy go first, carrying crosses and relics.", "phase": 0}, {"t": 16.329, "d": 6.976, "kind": "phase", "sub": "They pass beneath the north wall singing. The defenders jeer, raise crosses on the walls and insult them.", "phase": 1}, {"t": 24.005, "d": 5.12, "kind": "phase", "sub": "The procession turns south along the east wall and climbs the Mount of Olives.", "phase": 2}, {"t": 29.825, "d": 10.133, "kind": "phase", "sub": "On the Mount of Olives, Peter the Hermit preaches to the army, and the chaplain Arnulf after him. Raymond and Tancred, long at odds, are reconciled.", "phase": 3}, {"t": 40.658, "d": 8.832, "kind": "phase", "sub": "The army returns to its camps to build ladders and towers. The final assault begins on the night of 13 July.", "phase": 4}]}, "sc:first:crown": {"src": "audio/sc-first-crown.mp3", "dur": 49.635, "cues": [{"t": 0.35, "d": 2.645, "kind": "title", "sub": "Defender of the Holy Sepulchre."}, {"t": 3.895, "d": 9.131, "kind": "phase", "sub": "22 July 1099. A week after the city fell, the princes and clergy meet to choose a ruler for Jerusalem.", "phase": 0}, {"t": 13.726, "d": 5.739, "kind": "phase", "sub": "Some of the clergy argue that a spiritual leader should be chosen first, before any king.", "phase": 1}, {"t": 20.165, "d": 9.472, "kind": "phase", "sub": "The crown is offered to Raymond of Toulouse. He refuses. Raymond of Aguilers says the count would not bear the name of king in that city.", "phase": 2}, {"t": 30.337, "d": 5.312, "kind": "phase", "sub": "The princes turn to Godfrey. He agrees to govern, but he will not be called king.", "phase": 3}, {"t": 36.349, "d": 12.587, "kind": "phase", "sub": "He takes the title Advocatus Sancti Sepulchri, Defender of the Holy Sepulchre. Later tradition says he would not wear a crown of gold where Christ had worn a crown of thorns.", "phase": 4}]}};
